function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization, Mcp-Session-Id",
    "Content-Type": "application/json; charset=utf-8"
  };
}

function searchExhibitions(args = {}) {
  const q = (args.query || "").toLowerCase().trim();
  const city = (args.city || "").toLowerCase().trim();
  const cat = (args.category || "").toLowerCase().trim();
  const todayCST = new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10);
  const matches = EXHIBITIONS.filter(ex => {
    if (ex.end_date && ex.end_date <= todayCST) return false;
    const haystack = `${ex.name_en} ${ex.name_zh} ${ex.summary_en} ${(ex.subcategories || []).join(" ")} ${ex.city} ${ex.category}`.toLowerCase();
    const mQ = !q || haystack.includes(q);
    const mCity = !city || ex.city.toLowerCase().includes(city);
    const mCat = !cat || ex.category.toLowerCase().includes(cat);
    return mQ && mCity && mCat;
  });
  return {
    as_of_date_cst: todayCST,
    expired_shows_excluded: true,
    total_matches: matches.length,
    directory_url: "https://chinawithme.com/exhibitions/",
    json_feed_url: "https://chinawithme.com/data/exhibitions.json",
    remote_viewer_service: {
      url: "https://chinawithme.com/trade-show-visit-on-behalf-china",
      price_per_day_usd: 299,
      three_day_sprint_usd: 799,
      deliverables: [
        "Pre-show booth mapping & Mandarin technical questionnaire alignment",
        "On-site booth visits with high-res photos & live video calls",
        "Direct Mandarin engineering & MOQ/FOB pricing interviews",
        "Factory vs. trading company verification",
        "Structured 48-hour comparison report + physical sample consolidation"
      ]
    },
    exhibitions: matches
  };
}

