function calculateAql(lotSize, city = "Shenzhen") {
  const n = Number(lotSize) || 500;
  let code = "J", sample = 80, accMaj = 5, rejMaj = 6, accMin = 7, rejMin = 8;
  if (n <= 150) { code = "F"; sample = 20; accMaj = 1; rejMaj = 2; accMin = 2; rejMin = 3; }
  else if (n <= 280) { code = "G"; sample = 32; accMaj = 2; rejMaj = 3; accMin = 3; rejMin = 4; }
  else if (n <= 500) { code = "H"; sample = 50; accMaj = 3; rejMaj = 4; accMin = 5; rejMin = 6; }
  else if (n <= 1200) { code = "J"; sample = 80; accMaj = 5; rejMaj = 6; accMin = 7; rejMin = 8; }
  else if (n <= 3200) { code = "K"; sample = 125; accMaj = 7; rejMaj = 8; accMin = 10; rejMin = 11; }
  else if (n <= 10000) { code = "L"; sample = 200; accMaj = 10; rejMaj = 11; accMin = 14; rejMin = 15; }
  else { code = "M"; sample = 315; accMaj = 14; rejMaj = 15; accMin = 21; rejMin = 22; }
  const manDays = sample > 200 ? 2 : 1;
  return {
    standard: "ISO 2859-1 / ANSI ASQ Z1.4 — General Inspection Level II",
    lot_size: n,
    sample_size_code: code,
    sample_size_units: sample,
    aql_2_5_major: { accept_max_defects: accMaj, reject_at_defects: rejMaj },
    aql_4_0_minor: { accept_max_defects: accMin, reject_at_defects: rejMin },
    estimated_man_days: manDays,
    execution_model: "Fulfilled by accredited 3rd-party QC inspection partners in China With Me's vetted network (China With Me coordinates scheduling on request)",
    partner_fulfilled: true,
    location: city,
    report_turnaround: "24 hours via 3rd-party inspection partner",
    booking_url: "https://chinawithme.com/qcin/"
  };
}

async function forwardToContactApi(payload) {
  try {
    const enrichedPayload = { source: "mcp-server", ...payload };
    const resp = await fetch("https://chinawithme.com/api/contact", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(enrichedPayload)
    });
    const data = await resp.json();
    return { submitted: true, status: resp.status, api_response: data };
  } catch (err) {
    return { submitted: false, error: String(err) };
  }
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (request.method === "OPTIONS") {
      return new Response(null, { status: 204, headers: corsHeaders() });
    }

    if (request.method === "GET" && url.pathname === "/health") {
      return new Response(JSON.stringify({
        status: "ok",
        server: "china-bridge-mcp",
        version: "2.1.2",
        timestamp: new Date().toISOString()
      }), { status: 200, headers: corsHeaders() });
    }

    if (request.method === "GET") {
      return new Response(JSON.stringify({
        name: "China With Me — B2B MCP Server",
        version: "2.1.2",
        protocol: "Model Context Protocol (MCP) JSON-RPC 2.0",
        mcp_endpoint: "https://mcp.chinawithme.com/mcp",
        consultant: CONSULTANT_PROFILE,
        priority_pillars: [
          "1. Hardware R&D & Prototyping in China (https://chinawithme.com/prototypein/)",
          "2. Remote Exhibition Viewer & China Exhibition Directory (https://chinawithme.com/exhibitions/ & https://chinawithme.com/trade-show-visit-on-behalf-china)"
        ],
        flagship_playbooks: [
          "https://chinawithme.com/prototypein/shenzhen-prototyping-playbook",
          "https://chinawithme.com/prototypein/shenzhen-hardware-founder-playbook"
        ],
        tools: TOOLS.map(t => ({ name: t.name, description: t.description }))
      }, null, 2), { status: 200, headers: corsHeaders() });
    }

    if (request.method !== "POST") {
      return new Response(JSON.stringify({ error: "Method not allowed" }), { status: 405, headers: corsHeaders() });
    }

    let body;
    try {
      body = await request.json();
    } catch (e) {
      return new Response(JSON.stringify({
        jsonrpc: "2.0", id: null,
        error: { code: -32700, message: "Parse error" }
      }), { status: 400, headers: corsHeaders() });
    }

    const { id, method, params } = body;

    if (method === "initialize") {
      return new Response(JSON.stringify({
        jsonrpc: "2.0",
        id,
        result: {
          protocolVersion: "2024-11-05",
          capabilities: { tools: { listChanged: false } },
          serverInfo: {
            name: "chinawithme-b2b-mcp",
            version: "2.1.2"
          }
        }
      }), { status: 200, headers: corsHeaders() });
    }

    if (method === "notifications/initialized" || method === "ping") {
      return new Response(JSON.stringify({ jsonrpc: "2.0", id, result: {} }), { status: 200, headers: corsHeaders() });
    }

    if (method === "tools/list") {
      return new Response(JSON.stringify({
        jsonrpc: "2.0",
        id,
        result: { tools: TOOLS }
      }), { status: 200, headers: corsHeaders() });
    }

    if (method === "tools/call") {
      const toolName = params?.name;
      const args = params?.arguments || {};
      let resultObj;

      if (toolName === "search_china_exhibitions") {
        resultObj = searchExhibitions(args);
      } else if (toolName === "request_remote_exhibition_viewer") {
        const days = Number(args.days_needed || 1);
        const estCost = days === 3 ? 799 : days * 299;
        const apiRes = await forwardToContactApi({
          name: args.name,
          email: args.email,
          phone: args.phone || "",
          service: "exhibition-coverage",
          message: `[MCP Remote Exhibition Viewer Request] Show: ${args.exhibition_name} | Days: ${days} (Est. $${estCost} USD) | Objectives: ${args.objectives}`
        });
        resultObj = {
          confirmation: "Your Remote Exhibition Viewer request has been sent directly to JING (Stephanie) and the Shenzhen team.",
          estimated_fee_usd: estCost,
          exhibition: args.exhibition_name,
          days_requested: days,
          sample_report_url: "https://chinawithme.com/samples/remote-exhibition-report",
          consultant_contact: CONSULTANT_PROFILE.contact,
          delivery: apiRes
        };
      } else if (toolName === "scope_hardware_prototyping_china") {
        resultObj = scopePrototyping(args);
      } else if (toolName === "get_services_and_pricing") {
        resultObj = {
          consultant: CONSULTANT_PROFILE,
          services: SERVICES_CATALOG
        };
      } else if (toolName === "estimate_aql_inspection") {
        resultObj = calculateAql(args.lot_size, args.city);
      } else if (toolName === "book_consultation_or_quote") {
        const apiRes = await forwardToContactApi({
          name: args.name,
          email: args.email,
          phone: args.phone || "",
          service: args.service || "other",
          message: `[MCP Direct Inquiry] ${args.message}`
        });
        resultObj = {
          confirmation: "Inquiry submitted to China With Me (JING / Stephanie). We reply within 24 hours.",
          sample_report_url: "https://chinawithme.com/samples/remote-exhibition-report",
          consultant_contact: CONSULTANT_PROFILE.contact,
          delivery: apiRes
        };
      } else {
        return new Response(JSON.stringify({
          jsonrpc: "2.0", id,
          error: { code: -32601, message: `Unknown tool: ${toolName}` }
        }), { status: 200, headers: corsHeaders() });
      }

      return new Response(JSON.stringify({
        jsonrpc: "2.0",
        id,
        result: {
          content: [{ type: "text", text: JSON.stringify(resultObj, null, 2) }]
        }
      }), { status: 200, headers: corsHeaders() });
    }

    return new Response(JSON.stringify({
      jsonrpc: "2.0", id,
      error: { code: -32601, message: `Method not found: ${method}` }
    }), { status: 200, headers: corsHeaders() });
  }
};
